const items = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const binaryKeys = Object.keys(item.binary || {});
  if (binaryKeys.length === 0) throw new Error('No se recibió ninguna foto.');
  const key = binaryKeys[0];
  const binary = item.binary[key];
  const buffer = await this.helpers.getBinaryDataBuffer(i, key);
  const base64 = buffer.toString('base64');
  let mediaType = binary.mimeType || 'image/jpeg';
  if (!['image/jpeg','image/png','image/webp','image/gif'].includes(mediaType)) mediaType = 'image/jpeg';
  const sel = (item.json['Qué generar'] || 'Ambos').toLowerCase();
  const mode = sel.includes('stories') ? 'stories' : sel.includes('tiktok') ? 'tiktok' : 'both';
  items.push({ json: { base64, mediaType, mode, filename: binary.fileName || 'foto' } });
}
return items;

