const out = [];
for (const item of $input.all()) {
  const text = item.json.content?.[0]?.text || '';
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}') + 1;
  let plan;
  try { plan = JSON.parse(text.slice(start, end)); }
  catch (e) { plan = { error: 'No se pudo parsear', raw: text }; }
  out.push({ json: plan });
}
return out;

// Genera HTML bonito con el resultado para mostrar en el formulario
const p = $input.first().json;

if (p.error) {
  return [{ json: { html: `<div style="font-family:sans-serif;padding:24px;color:#ff6b6b">❌ Error: ${p.error}</div>` } }];
}

let html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{background:#0a0a0a;color:#fff;font-family:'Helvetica Neue',sans-serif;padding:20px}
.logo{font-family:Georgia,serif;font-size:26px;letter-spacing:3px;margin-bottom:24px;color:#fff}
.section{margin-bottom:28px}
.section-title{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:#888;margin-bottom:12px;border-left:3px solid #e8175d;padding-left:8px}
.analysis{font-size:14px;color:#aaa;line-height:1.6;background:#1a1a1a;padding:14px;border-radius:8px}
.story{background:#1a1a1a;border-radius:8px;padding:14px;margin-bottom:10px}
.story-type{display:inline-block;background:#e8175d;color:#fff;font-size:10px;font-weight:700;padding:2px 8px;border-radius:3px;margin-bottom:8px}
.story-overlay{font-size:18px;font-weight:700;margin-bottom:6px}
.story-caption{font-size:13px;color:#aaa;line-height:1.5}
.story-sticker{font-size:12px;color:#e8175d;margin-top:6px}
.script-row{display:flex;gap:10px;padding:8px 0;border-bottom:1px solid #222;font-size:13px}
.script-time{color:#e8175d;font-weight:700;font-size:11px;min-width:90px}
.audio-row{margin-top:10px;font-size:13px;color:#aaa}
.caption-box{background:#1a1a1a;border-radius:8px;padding:16px;font-size:14px;line-height:1.7;white-space:pre-wrap}
.hashtags{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
.hashtag{background:rgba(232,23,93,.15);border:1px solid rgba(232,23,93,.3);color:#e8175d;padding:4px 10px;border-radius:20px;font-size:12px}
.copy-btn{display:block;width:100%;margin-top:10px;background:#e8175d;color:#fff;border:none;border-radius:6px;padding:10px;font-size:13px;font-weight:700;cursor:pointer;letter-spacing:1px}
.copy-btn:active{opacity:.8}
.prompts{background:#1a1a1a;border-radius:8px;padding:14px;font-size:12px;color:#888;line-height:1.6}
</style></head><body>
<div class="logo">kÖr</div>`;

// Análisis
if (p.analysis) {
  html += `<div class="section"><div class="section-title">Análisis</div><div class="analysis">${p.analysis}</div></div>`;
}

// Historias
if (p.stories && p.stories.length) {
  html += `<div class="section"><div class="section-title">📱 Historias</div>`;
  p.stories.forEach(s => {
    html += `<div class="story">
      <span class="story-type">${s.type}</span>
      <div class="story-overlay">"${s.overlay_text || ''}"</div>
      <div class="story-caption">${s.caption || ''}</div>
      ${s.sticker ? `<div class="story-sticker">💬 ${s.sticker}</div>` : ''}
    </div>`;
  });
  html += `</div>`;
}

// TikTok
if (p.tiktok && p.tiktok.format) {
  const tt = p.tiktok;
  html += `<div class="section"><div class="section-title">🎬 TikTok [${tt.format}] — ${tt.duration || ''}</div>`;
  if (tt.script) {
    tt.script.forEach(step => {
      html += `<div class="script-row"><span class="script-time">${step.time || ''}</span><span>${step.action || ''}</span></div>`;
    });
  }
  if (tt.audio) html += `<div class="audio-row">🎵 Audio: ${tt.audio}</div>`;
  if (tt.on_screen_text) html += `<div class="audio-row">📝 Texto: ${tt.on_screen_text}</div>`;
  html += `</div>`;
}

// Caption
if (p.instagram_caption) {
  const cap = p.instagram_caption.replace(/'/g, "&#39;");
  html += `<div class="section"><div class="section-title">✍️ Caption Instagram</div>
    <div class="caption-box" id="cap">${p.instagram_caption}</div>
    <button class="copy-btn" onclick="navigator.clipboard.writeText(document.getElementById('cap').innerText).then(()=>{this.textContent='✓ Copiado';setTimeout(()=>this.textContent='Copiar Caption',1500)})">Copiar Caption</button>
  </div>`;
}

// Hashtags
if (p.hashtags && p.hashtags.length) {
  const tagStr = p.hashtags.map(t => t.startsWith('#') ? t : '#'+t).join(' ');
  const tagStrEsc = tagStr.replace(/'/g, "&#39;");
  html += `<div class="section"><div class="section-title">#️⃣ Hashtags</div>
    <div class="hashtags" id="tags">${p.hashtags.map(t=>`<span class="hashtag">${t.startsWith('#')?t:'#'+t}</span>`).join('')}</div>
    <button class="copy-btn" onclick="navigator.clipboard.writeText('${tagStrEsc}').then(()=>{this.textContent='✓ Copiado';setTimeout(()=>this.textContent='Copiar Hashtags',1500)})">Copiar Hashtags</button>
  </div>`;
}

// Prompts Higgsfield
if (p.higgsfield_prompts && p.higgsfield_prompts.length) {
  html += `<div class="section"><div class="section-title">🎨 Prompts Higgsfield</div><div class="prompts">${p.higgsfield_prompts.join('<br><br>')}</div></div>`;
}

html += `</body></html>`;

return [{ json: { html } }];
